mapper.select:
select id, merchant_id, family_id, user_id, meal_slot_id, service_date, remark, status
from carts
where family_id = #{familyId}
  and user_id = #{memberId}
  and meal_slot_id = #{mealSlotId}
  and service_date = #{serviceDate}
  and status = 'active'
limit 1

select ci.id, ci.cart_id, ci.dish_id, ci.dish_name_snapshot, ci.price, ci.quantity, ci.item_remark
from cart_items ci
join carts c on c.id = ci.cart_id
where ci.id = #{itemId}
  and c.family_id = #{familyId}
  and c.user_id = #{memberId}
  and c.status = 'active'
limit 1

mapper.update:
update cart_items
set quantity = #{quantity},
    item_remark = #{itemRemark}
where id = #{id}

mapper.delete:
delete ci
from cart_items ci
join carts c on c.id = ci.cart_id
where ci.id = #{itemId}
  and c.family_id = #{familyId}
  and c.user_id = #{memberId}
  and c.status = 'active'

mapper.update:
update carts
set remark = #{remark}
where id = #{cartId}

update carts
set status = 'submitted'
where family_id = #{familyId}
  and user_id = #{memberId}
  and meal_slot_id = #{mealSlotId}
  and service_date = #{serviceDate}
  and status = 'active'
